    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; cells=set()
                while st:
                    y,x=st.pop()
                    if seen[y][x]: continue
                    seen[y][x]=True; cells.add((y,x))
                    for dy,dx in ((-1,0),(1,0),(0,-1),(0,1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]!=bg and not seen[ny][nx]: st.append((ny,nx))
                out.append(cells)
    return out
def norm(cells):
    my=min(y for y,x in cells); mx=min(x for y,x in cells)
    return tuple(sorted((y-my,x-mx) for y,x in cells))
def touches(a,b):
    return any((y+dy,x+dx) in b for y,x in a for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)))
for n in range(1,8):
    gi=G['Demo pair %d input'%n]; go=G['Demo pair %d output'%n]
    H,W=len(gi),len(gi[0])
    bg=Counter(v for r in gi for v in r).most_common(1)[0][0]
    cs=comps(gi,bg)
    diffs={(y,x) for y in range(H) for x in range(W) if gi[y][x]!=go[y][x]}
    chid=[i for i,c_ in enumerate(cs) if c_&diffs][0]
    col=int(gi[min(cs[chid])]); tgt=int(go[next(iter(diffs))])
    sh=norm(cs[chid])
    peers=[]
    for i in range(len(cs)):
        if i!=chid and norm(cs[i])==sh:
            r,c2=min(cs[i])
            peers.append(('id',i,'C',int(gi[r][c2]),'sz',len(cs[i])) )
    print('demo',n,'CHANGED id',chid,'color',col,'->',tgt,'pos',min(cs[chid]))
    for p in peers: print(p)

import numpy as np, os, re
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
